db.country.aggregate([
    { $match: { continent: "Asia" } }, // Find all Asian countries
    { $group: { _id: null, minPopulation: { $min: "$population" } } }, // Get the minimum population of any Asian country
    { $sort: { "minPopulation": 1 } }, // Sort by the minimum population in ascending order
    { $project: { _id: 0, minPopulation: 1 } }, // Project only the minimum population
    { $lookup: {
        from: "country",
        localField: "minPopulation",
        foreignField: "population",
        as: "asianCountries"
    }}, // Join the Asian countries with the original collection where population is less than the minimum Asian population
    { $unwind: "$asianCountries" }, // Flatten the array of Asian countries
    { $match: { $and: [{ continent: "Africa" }, { population: { $lt: "$minPopulation" } }] } }, // Filter African countries with a population less than the minimum Asian population
    { $project: { _id: 0, name: 1, continent: 1, population: 1 } } // Project the required fields for African countries with a population less than any Asian country
]);

